import cc.iili.tools.crossmool.bean.CiphertextSignaturePair;
import cc.iili.tools.crossmool.tool.SM2Util;
import cc.iili.tools.crossmool.tool.SM3Util;
import cc.iili.tools.crossmool.tool.SM4Util;
import cc.iili.tools.crossmool.util.HexUtil;

import java.io.FileReader;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Java-Go SM2/SM3/SM4 Interoperability Test - Go Data Verifier
 * Verifies test data generated by Go against Java implementations.
 */
public class VerifyGoInteropData {

    private static int passCount = 0;
    private static int failCount = 0;

    private static void report(String name, boolean pass, String detail) {
        String status = pass ? "PASS" : "FAIL";
        if (pass) {
            passCount++;
        } else {
            failCount++;
        }
        if (detail != null && !detail.isEmpty()) {
            System.out.printf("[%s] %s - %s%n", status, name, detail);
        } else {
            System.out.printf("[%s] %s%n", status, name);
        }
    }

    public static void main(String[] args) throws Exception {
        String jsonPath = args.length > 0 ? args[0] : "testcase/go_java_test_data.json";

        System.out.println("========================================");
        System.out.println("  Go-Java Interoperability Verification");
        System.out.println("========================================");

        // Read JSON file
        StringBuilder jsonContent = new StringBuilder();
        try (FileReader reader = new FileReader(jsonPath)) {
            int c;
            while ((c = reader.read()) != -1) {
                jsonContent.append((char) c);
            }
        }

        String json = jsonContent.toString();
        String testMessage = extractJsonString(json, "test_message");
        System.out.printf("Test Message: %s%n%n", testMessage);

        // Extract SM2 section
        String sm2Section = extractJsonObject(json, "sm2");
        verifySM2(testMessage, sm2Section);

        // Extract SM3 section
        String sm3Section = extractJsonObject(json, "sm3");
        verifySM3(testMessage, sm3Section);

        // Extract SM4 section
        String sm4Section = extractJsonObject(json, "sm4");
        verifySM4(sm4Section);

        System.out.println("========================================");
        System.out.printf("Total: %d PASS, %d FAIL%n", passCount, failCount);
        if (failCount > 0) {
            System.out.println("RESULT: FAILED");
            System.exit(1);
        }
        System.out.println("RESULT: ALL PASSED");
    }

    private static String extractJsonString(String json, String key) {
        Pattern pattern = Pattern.compile("\"" + key + "\"\\s*:\\s*\"([^\"]*)\"");
        Matcher matcher = pattern.matcher(json);
        if (matcher.find()) {
            return matcher.group(1);
        }
        return "";
    }

    private static String extractJsonObject(String json, String key) {
        int startKey = json.indexOf("\"" + key + "\"");
        if (startKey == -1) return "";
        int startBrace = json.indexOf('{', startKey);
        if (startBrace == -1) return "";
        int braceCount = 1;
        int i = startBrace + 1;
        while (i < json.length() && braceCount > 0) {
            char c = json.charAt(i);
            if (c == '{') braceCount++;
            else if (c == '}') braceCount--;
            i++;
        }
        return json.substring(startBrace, i);
    }

    private static void verifySM2(String testMessage, String sm2) {
        System.out.println("--- SM2 Tests ---");

        String pubKeyHex = extractJsonString(sm2, "public_key_hex");
        String privKeyHex = extractJsonString(sm2, "private_key_hex");
        String pubKeyBase64 = extractJsonString(sm2, "public_key_base64");
        String privKeyBase64 = extractJsonString(sm2, "private_key_base64");

        String ciphertextHex = extractJsonString(sm2, "ciphertext_hex");
        String ciphertextBase64 = extractJsonString(sm2, "ciphertext_base64");

        String signatureHex = extractJsonString(sm2, "signature_hex");
        String signatureBase64 = extractJsonString(sm2, "signature_base64");

        // Extract encrypt_sign section
        String encSignSection = extractJsonObject(sm2, "encrypt_sign");
        String encSignHex = extractJsonObject(encSignSection, "hex");
        String encSignBase64 = extractJsonObject(encSignSection, "base64");

        String encSignCiphHex = extractJsonString(encSignHex, "ciphertext");
        String encSignSigHex = extractJsonString(encSignHex, "signature");
        String encSignCiphBase64 = extractJsonString(encSignBase64, "ciphertext");
        String encSignSigBase64 = extractJsonString(encSignBase64, "signature");

        // 1. Decrypt Hex ciphertext
        String decryptedHex = SM2Util.decrypt(ciphertextHex, privKeyHex);
        report("SM2 Decrypt Hex", testMessage.equals(decryptedHex), "got=\"" + decryptedHex + "\"");

        // 2. Decrypt Base64 ciphertext
        String decryptedBase64 = SM2Util.decrypt(ciphertextBase64, privKeyBase64);
        report("SM2 Decrypt Base64", testMessage.equals(decryptedBase64), "got=\"" + decryptedBase64 + "\"");

        // 3. Verify Hex signature
        boolean verifyHex = SM2Util.verify(testMessage, pubKeyHex, signatureHex);
        report("SM2 Verify Hex", verifyHex, "");

        // 4. Verify Base64 signature
        boolean verifyBase64 = SM2Util.verify(testMessage, pubKeyBase64, signatureBase64);
        report("SM2 Verify Base64", verifyBase64, "");

        // 5. VerifyDecrypt Hex
        CiphertextSignaturePair pairHex = new CiphertextSignaturePair(encSignCiphHex, encSignSigHex);
        String verifyDecHex = SM2Util.verifyDecrypt(pairHex, pubKeyHex, privKeyHex);
        report("SM2 VerifyDecrypt Hex", testMessage.equals(verifyDecHex), "got=\"" + verifyDecHex + "\"");

        // 6. VerifyDecrypt Base64
        CiphertextSignaturePair pairBase64 = new CiphertextSignaturePair(encSignCiphBase64, encSignSigBase64);
        String verifyDecBase64 = SM2Util.verifyDecrypt(pairBase64, pubKeyBase64, privKeyBase64);
        report("SM2 VerifyDecrypt Base64", testMessage.equals(verifyDecBase64), "got=\"" + verifyDecBase64 + "\"");

        System.out.println();
    }

    private static void verifySM3(String testMessage, String sm3) {
        System.out.println("--- SM3 Tests ---");

        String digestHex = extractJsonString(sm3, "digest_hex");
        String digestBase64 = extractJsonString(sm3, "digest_base64");
        String hmacKeyHex = extractJsonString(sm3, "hmac_key_hex");
        String hmacKeyBase64 = extractJsonString(sm3, "hmac_key_base64");
        String hmacHex = extractJsonString(sm3, "hmac_hex");
        String hmacBase64 = extractJsonString(sm3, "hmac_base64");

        // 1. Compute digest and compare with Hex
        String javaDigestHex = SM3Util.digestToStr(testMessage, false);
        report("SM3 Digest Hex", digestHex.equals(javaDigestHex),
                "go=" + digestHex + " java=" + javaDigestHex);

        // 2. Compute digest and compare with Base64
        String javaDigestBase64 = SM3Util.digestToStr(testMessage, true);
        report("SM3 Digest Base64", digestBase64.equals(javaDigestBase64),
                "go=" + digestBase64 + " java=" + javaDigestBase64);

        // 3. HMAC-SM3 with Hex key
        String javaHmacHex = SM3Util.hmacToStr(hmacKeyHex, testMessage, false);
        report("HMAC-SM3 Hex key", hmacHex.equals(javaHmacHex),
                "go=" + hmacHex + " java=" + javaHmacHex);

        // 4. HMAC-SM3 with Base64 key
        String javaHmacBase64 = SM3Util.hmacToStr(hmacKeyBase64, testMessage, true);
        report("HMAC-SM3 Base64 key", hmacBase64.equals(javaHmacBase64),
                "go=" + hmacBase64 + " java=" + javaHmacBase64);

        System.out.println();
    }

    private static void verifySM4(String sm4) {
        System.out.println("--- SM4-GCM Tests ---");

        String keyHex = extractJsonString(sm4, "key_hex");
        String gcmCiphertextHex = extractJsonString(sm4, "gcm_ciphertext_hex");
        String gcmCiphertextBase64 = extractJsonString(sm4, "gcm_ciphertext_base64");

        byte[] keyBytes = HexUtil.decodeHexStr(keyHex);

        // 1. Decrypt Hex GCM ciphertext - convert hex to base64 first
        try {
            byte[] cipherBytes = HexUtil.decodeHexStr(gcmCiphertextHex);
            String cipherBase64 = java.util.Base64.getEncoder().encodeToString(cipherBytes);
            String decryptedHex = SM4Util.decryptGcmNativeToString(keyBytes, cipherBase64);
            report("SM4-GCM Decrypt Hex", true, "got=\"" + decryptedHex + "\"");
        } catch (Exception e) {
            report("SM4-GCM Decrypt Hex", false, e.getMessage());
        }

        // 2. Decrypt Base64 GCM ciphertext
        try {
            String decryptedBase64 = SM4Util.decryptGcmNativeToString(keyBytes, gcmCiphertextBase64);
            report("SM4-GCM Decrypt Base64", true, "got=\"" + decryptedBase64 + "\"");
        } catch (Exception e) {
            report("SM4-GCM Decrypt Base64", false, e.getMessage());
        }

        System.out.println();
    }
}